jsonTools.init:
function init(eli) {
  // DEBUG marker — run `window.__askDockVersion` in the console to confirm
  // THIS build is the one running. If it's undefined, you're on a stale bundle.
  try { window.__askDockVersion = "2026-06-03-r16-handle-in-body"; } catch (_e) {}
  // Restored: honor the on-home rule (the dashboard's Ask ELI bar already covers that surface).
  var _FORCE_ALWAYS_SHOW = false;
  var SETTING_KEY = "ask_dock_enabled";
  var _enabled = true;
  var _handle = null, _backdrop = null, _panel = null, _panelBody = null;
  var _built = false, _isOpen = false, _hideTimer = null, _visTimer = null, _openedAt = 0;

  // Allowlist of tool ids where the chevron should appear. When non-empty,
  // visibility is gated to the active tool's id (tracked via kernel
  // bus events `tool:open` and `home:navigate`). When empty, falls back
  // to legacy behavior (show on all non-home/non-loading screens). Edit
  // the Set below to control which tools get the dock.
  var _ALLOWED_TOOL_IDS = new Set([
    "legal_risks",
    "build_draft",
    "final_review",
    "error_review",
    "review_redlines",
    "auto_emailer",
    "usage_risks",
    "legal_review",
    "compare",
  ]);
  var _currentToolId = null;

  // Reliable home detection: the home Ask ELI input bar (._eli3_home_ask)
  // exists ONLY on the dashboard. It's painted by ask_eli's registerHomeSlot
  // and lives in #_eli3_home_slots. Tools replace the dashboard root, so
  // this element vanishes. Much more reliable than the tile-grid host check
  // (which can persist or flicker during transitions).
  function _isOnHome() {
    var bar = document.querySelector("._eli3_home_ask");
    return !!(bar && bar.getClientRects().length > 0);
  }
  // True when the user is in the full Ask ELI tile (not just our dock).
  // The full tool paints a `._eli3_chat_root` directly into the dashboard
  // root; our dock paints the same class inside `#_eli3_askdock_panel`.
  // We hide the dock handle when full Ask ELI is the active screen — having
  // a chevron to re-open Ask ELI on top of Ask ELI would be redundant.
  function _isInFullAskEli() {
    var roots = document.querySelectorAll("._eli3_chat_root");
    for (var i = 0; i < roots.length; i++) {
      if (!roots[i].closest("#_eli3_askdock_panel")) return true;
    }
    return false;
  }
  // True while any full-screen loading overlay is up. The kernel paints
  // `#_eli3_loading_overlay` and tools paint their own variants (e.g.
  // `#_eli3_rr_smile_overlay` from review_redlines) — but every loader
  // shares the class `_eli3_er_progress_overlay`. Matching on the CLASS
  // catches every variant: kernel default, the brushing-teeth smile loader,
  // and any future per-tool overlay that follows the convention.
  // Mounting changes on body fire the resurrection MutationObserver below,
  // which re-runs visibility.
  function _isLoadingScreen() {
    return !!document.querySelector("._eli3_er_progress_overlay");
  }
  function _updateVisibility() {
    if (!_handle) return;
    // Never hide while the panel is open — user needs the chevron to close.
    if (_isOpen) { _handle.style.setProperty("display", "inline-flex", "important"); return; }
    if (_enabled === false) { _handle.style.display = "none"; return; }
    // Hide on the home dashboard (the home Ask ELI bar covers it there).
    if (_isOnHome()) { _handle.style.display = "none"; return; }
    // Hide during full-screen kernel loading overlays.
    if (_isLoadingScreen()) { _handle.style.display = "none"; return; }
    // Hide when the user is in the full Ask ELI tool — having a "open
    // Ask ELI" chevron on top of Ask ELI itself is redundant. (Kept as
    // defense-in-depth alongside the allowlist check below: ask_eli is
    // never on the allowlist, but this DOM check also catches paths that
    // don't fire `tool:open` — e.g. ask_eli launched via dispatch.)
    if (_isInFullAskEli()) { _handle.style.display = "none"; return; }
    // Allowlist gate — always enforced when populated. Only an explicit
    // tool id in the allowlist gets the chevron. Colleagues on an older
    // kernel that doesn't emit `tool:open` will see no chevron until they
    // update — acceptable tradeoff vs. the wrong-context appearances the
    // auto-detect was producing (e.g. Settings gear path).
    if (_ALLOWED_TOOL_IDS.size > 0) {
      if (!_currentToolId || !_ALLOWED_TOOL_IDS.has(_currentToolId)) {
        _handle.style.display = "none"; return;
      }
    }
    _handle.style.setProperty("display", "inline-flex", "important");
  }
  // Re-evaluate on any dashboard/tool content swap. #output persists; its
  // subtree changes when home renders, a v3 tool swaps the root, or a v2
  // tool takes over. Debounced; the check itself is a cheap getElementById.
  function _watchView() {
    var out = document.getElementById("output");
    if (!out) { setTimeout(_watchView, 400); return; }
    try {
      var mo = new MutationObserver(function () {
        if (_visTimer) return;
        _visTimer = setTimeout(function () { _visTimer = null; _updateVisibility(); }, 80);
      });
      mo.observe(out, { childList: true, subtree: true });
    } catch (_e) {}
    _updateVisibility();
  }

  // ── Kill switch via eli.settings (instant off, no uninstall) ──────
  // CRITICAL: default ON. Only an EXPLICIT `false` disables. At preload-idle
  // boot the settings provider may not be ready yet and get() returns a
  // falsy/undefined value — treating that as "disabled" previously skipped
  // the entire build (the real root cause of the handle never appearing).
  // The build is NEVER gated on this; visibility is.
  function _refreshEnabled() {
    try {
      if (eli.settings && typeof eli.settings.get === "function") {
        var v = eli.settings.get(SETTING_KEY);
        _enabled = (v === false) ? false : true; // undefined/not-ready => ON
      }
    } catch (_e) {}
    if (_built) _updateVisibility();
  }
  try {
    if (eli.settings && typeof eli.settings.register === "function") {
      eli.settings.register(SETTING_KEY, {
        default: true,
        type: "boolean",
        storage: { type: "ls_blob_field", key: "eli_user_settings", field: "askDockEnabled" },
        apply: function (v) { _enabled = (v === false) ? false : true; if (_built) _updateVisibility(); },
        adminPushable: true,
        describe: "Show the pull-down Ask ELI dock under the header",
      });
    }
  } catch (_e) {}
  _refreshEnabled();

  // ── Position chrome relative to the live header bottom edge ───────
  function _headerBottom() {
    try {
      var h = document.querySelector(".header");
      if (h) {
        var r = h.getBoundingClientRect();
        if (r && r.bottom > 0) return Math.round(r.bottom);
      }
    } catch (_e) {}
    return 0;
  }
  function _positionChrome() {
    var top = _headerBottom();
    // 2026-06-04: +2px below the header. The kernel header casts a
    // downward `box-shadow: var(--shadow-header)` that extends past its
    // render box — sitting the chevron at exactly headerBottom puts it
    // INSIDE the shadow strip, which reads as overlap visually. The
    // 2px buffer clears the shadow without leaving an obvious gap.
    if (_handle) _handle.style.top = (top + 2) + "px";
    if (_backdrop) _backdrop.style.top = top + "px";
    if (_panel) {
      _panel.style.top = top + "px";
      // Smaller panel — leaves ~70px of backdrop visible at the bottom and
      // sits slightly inset from the sides via the stylesheet's max-width.
      _panel.style.height = "calc(100vh - " + (top + 70) + "px)";
    }
  }

  // Keep the handle in document.body (position:fixed). Inside-the-header
  // approach trapped the hanging visible portion in the header's stacking
  // context, where tool content (a later sibling) painted ON TOP — so
  // clicks went to the tool, not the handle. Visual fusion is achieved by
  // sampling the header gradient's OUTER color (the value at the header's
  // bottom edge) and painting the handle solid in that color — the join
  // is between two regions of the same color, no seam.
  // Cheap perceptual luminance from any CSS color string we're likely to
  // sample (#rgb, #rrggbb, rgb(), rgba()). Returns 0..1. Used to pick a
  // readable text color against the sampled header bg — trusting the
  // header's computed color is unreliable (e.g. in body.light-mode the
  // kernel sets --text-primary to dark navy globally, but the header
  // gradient's outer stop is still #262626 — that combination is
  // unreadable. Pick text by luminance instead).
  function _luminance(c) {
    if (!c) return 0;
    var s = String(c).trim(), m, r, g, b;
    if ((m = s.match(/^#([0-9a-f])([0-9a-f])([0-9a-f])$/i))) {
      r = parseInt(m[1] + m[1], 16); g = parseInt(m[2] + m[2], 16); b = parseInt(m[3] + m[3], 16);
    } else if ((m = s.match(/^#([0-9a-f]{6})$/i))) {
      r = parseInt(m[1].slice(0, 2), 16); g = parseInt(m[1].slice(2, 4), 16); b = parseInt(m[1].slice(4, 6), 16);
    } else if ((m = s.match(/^rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/))) {
      r = +m[1]; g = +m[2]; b = +m[3];
    } else { return 0; }
    return (0.299 * r + 0.587 * g + 0.114 * b) / 255;
  }
  // Parse a CSS color string into [r,g,b] (alpha ignored). Returns null
  // on unparsable input. Shared with _luminance for color math.
  function _toRgb(c) {
    if (!c) return null;
    var s = String(c).trim(), m;
    if ((m = s.match(/^#([0-9a-f])([0-9a-f])([0-9a-f])$/i))) {
      return [parseInt(m[1] + m[1], 16), parseInt(m[2] + m[2], 16), parseInt(m[3] + m[3], 16)];
    }
    if ((m = s.match(/^#([0-9a-f]{6})$/i))) {
      return [parseInt(m[1].slice(0, 2), 16), parseInt(m[1].slice(2, 4), 16), parseInt(m[1].slice(4, 6), 16)];
    }
    if ((m = s.match(/^rgba?\(\s*(\d+)\s*,\s*(\d+)\s*,\s*(\d+)/))) {
      return [+m[1], +m[2], +m[3]];
    }
    return null;
  }
  // Linear-interpolate between two CSS colors. `t` = weight of c2 (0 → all c1,
  // 1 → all c2). Returns an `rgb(...)` string. Used to estimate the gradient
  // color at the seam between header and handle for linear gradients —
  // sampling just the LAST stop misses by ~30% on directional gradients
  // (135° sky-to-edge themes) because the chevron's center-bottom position
  // is roughly 60% along the gradient axis, not 100%.
  function _mix(c1, c2, t) {
    var a = _toRgb(c1), b = _toRgb(c2);
    if (!a || !b) return c2;
    return "rgb(" +
      Math.round(a[0] * (1 - t) + b[0] * t) + "," +
      Math.round(a[1] * (1 - t) + b[1] * t) + "," +
      Math.round(a[2] * (1 - t) + b[2] * t) + ")";
  }
  // Extract every color stop from a gradient string in source order.
  // Catches "#abc", "#aabbcc", "rgb(...)" and "rgba(...)".
  function _extractStops(bgImage) {
    var out = [], re = /(rgba?\([^)]+\)|#[0-9a-fA-F]{3,8})/g, m;
    while ((m = re.exec(bgImage)) !== null) out.push(m[1]);
    return out;
  }
  function _matchHeaderLook() {
    if (!_handle) return;
    try {
      var h = document.querySelector(".header");
      if (!h) return;
      var cs = getComputedStyle(h);
      var bgImage = cs.backgroundImage || "";
      var solid = "";
      // Gradient-type-aware sampling. The chevron sits at the bottom-center
      // of the header; what color is painted there depends on the gradient
      // type:
      //   • radial-gradient(... at 20% 20%): focal point is top-left, so
      //     the bottom-center is near the outer ring → LAST stop is right.
      //     (Dark mode + default theme — works.)
      //   • linear-gradient(135deg, A, B): direction is top-left → bottom-
      //     right. At the bottom-CENTER, position is ≈60% along the axis,
      //     NOT 100%. Sampling the last stop misses noticeably on light
      //     themes (theme-classic-white etc.) where A and B differ by
      //     enough to be visible. Mix first + last at t=0.6 instead.
      if (/^linear-gradient/i.test(bgImage)) {
        var stops = _extractStops(bgImage);
        if (stops.length >= 2) {
          solid = _mix(stops[0], stops[stops.length - 1], 0.6);
        } else if (stops.length === 1) {
          solid = stops[0];
        }
      }
      // Radial / unrecognized → original "last stop" path. Reliable for
      // radial-gradient(... at corner ...) which is what the default
      // theme uses for both light and dark mode.
      if (!solid) {
        var lastColor = bgImage.match(/(rgba?\([^)]+\)|#[0-9a-fA-F]{3,8})\s*(?:[\d.]+%?\s*)?\)\s*$/);
        if (lastColor && lastColor[1]) solid = lastColor[1];
      }
      if (!solid) solid = cs.backgroundColor;
      if (solid && solid.indexOf("rgba(0, 0, 0, 0)") === -1) {
        _handle.style.setProperty("background", solid, "important");
        _handle.style.setProperty("background-image", "none", "important");
      }
      // Pick text from bg luminance instead of cs.color — see _luminance
      // doc above. Threshold 0.55 keeps mid-gray bgs (like #888) on the
      // light-text side, which reads better against the gold border.
      var sampleBg = solid || cs.backgroundColor || "";
      var lum = _luminance(sampleBg);
      var textColor = lum > 0.55 ? "#0f172a" : "#f8fafc";
      _handle.style.setProperty("color", textColor, "important");
      // Chevron gets the matching contrast-tuned gold too — the CSS
      // light-mode rule (#b8901f) was tuned for a white bg that JS no
      // longer paints. Brighter gold #e7c14e on dark; deeper #b8901f
      // on actually-light backgrounds.
      var chev = _handle.querySelector("._eli3_askdock_chev");
      if (chev) chev.style.setProperty("color", lum > 0.55 ? "#b8901f" : "#e7c14e", "important");
    } catch (_e) {}
  }

  // ── Build the handle + panel once (idempotent + retry-safe) ──────
  function _build() {
    // Treat as built only if the handle is ACTUALLY in the DOM. Guarding on
    // the _built flag alone let a half-finished prior attempt (flag set, then
    // threw before appendChild) block all future builds.
    if (_built && document.getElementById("_eli3_askdock_handle")) return;
    // Sweep any partial leftovers from a failed attempt so we never dupe.
    ["_eli3_askdock_handle", "_eli3_askdock_backdrop", "_eli3_askdock_panel"].forEach(function (id) {
      var el = document.getElementById(id);
      if (el && el.parentNode) el.parentNode.removeChild(el);
    });
    _built = true;

    _handle = document.createElement("button");
    _handle.type = "button";
    _handle.id = "_eli3_askdock_handle";
    _handle.className = "_eli3_askdock_handle";
    _handle.setAttribute("data-askdock", "1");
    _handle.title = "Ask ELI — open from anywhere";
    _handle.innerHTML =
      '<span class="_eli3_askdock_label">Ask</span>' +
      '<span class="_eli3_askdock_chev">▾</span>';
    // position:fixed in document.body so it's above all tool content and
    // freely clickable. top is set by _positionChrome to the header's bottom
    // edge (-1 for a 1px overlap → invisible seam). The solid color is
    // matched to the header gradient's OUTER stop (#262626-equivalent) by
    // _matchHeaderLook, so the visible join reads as a continuation of the
    // header. No top box-shadow (so no "behind the handle" gap is visible).
    // Sits flush against the header's bottom edge (top is set to the live
    // header.bottom by _positionChrome). No box-shadow — the kernel header
    // already casts one downward, and adding our own makes the handle read
    // as a floating button instead of an extrusion of the header.
    // top:32 matches the kernel's --layout-header-h default and is what
    // _positionChrome lands on once the header is measurable. Keeping
    // the same value here means the chevron sits flush from the very
    // first paint instead of starting at 31 (overlapping) and snapping
    // to 32 after the first _positionChrome run.
    // 2026-06-04: clip-path trapezoid — wider top, narrower bottom.
    // Reads as the header tapering DOWN into the chevron rather than as
    // a rectangle stuck below. Gold outline on the slanted sides + bottom
    // is drawn via three stacked drop-shadows (border doesn't follow
    // clip-path; drop-shadow does). NO upward shadow → no top outline,
    // preserving the seamless seam with the header.
    _handle.style.cssText =
      "position:fixed;left:50%;top:34px;transform:translateX(-50%) translateZ(0);" +
      "z-index:10002;display:inline-flex;align-items:center;gap:9px;padding:4px 26px 6px;" +
      "border:none;border-radius:0;" +
      "clip-path:polygon(0 0,100% 0,calc(100% - 10px) 100%,10px 100%);" +
      "filter:drop-shadow(-2px 0 0 #c9a227) drop-shadow(2px 0 0 #c9a227) drop-shadow(0 2px 0 #c9a227);" +
      "cursor:pointer;font:700 10px/1 Inter,'Segoe UI',system-ui,sans-serif;" +
      "letter-spacing:0.1em;text-transform:uppercase;box-shadow:none;";
    // Simple bubble-phase click handler. The handle lives in document.body
    // (not inside the header), so the click's bubble path is span → handle
    // → body — the kernel's header click handler is NOT in this path and
    // can't fire. Earlier I had a CAPTURE-phase stopPropagation listener
    // here, but capture fires on ancestors on the way DOWN to the target:
    // since the click target is the LABEL SPAN (a child of the handle),
    // the handle is an ancestor in capture phase. stopPropagation in
    // capture aborted the event before it reached the span target,
    // which meant the bubble phase never ran and my handler never fired.
    _handle.setAttribute("data-ask-dock-handle", "1");
    _handle.addEventListener("click", function () {
      _isOpen ? _close() : _openDock();
    });

    _backdrop = document.createElement("div");
    _backdrop.id = "_eli3_askdock_backdrop";
    _backdrop.className = "_eli3_askdock_backdrop";
    _backdrop.setAttribute("data-askdock", "1");
    _backdrop.style.display = "none";
    _backdrop.onclick = _close;
    document.body.appendChild(_backdrop);

    _panel = document.createElement("div");
    _panel.id = "_eli3_askdock_panel";
    _panel.className = "_eli3_askdock_panel";
    _panel.setAttribute("data-askdock", "1");
    _panel.style.display = "none";
    // Slimline dock header — just a close button bar. Ask ELI renders its
    // OWN header inside the chat shell (icon + title + back arrow), so a
    // dock header here would duplicate it. We collapse to a thin sliver
    // with just the close ✕ floating in the corner.
    _panel.innerHTML =
      '<button type="button" class="_eli3_askdock_pclose" title="Close panel">✕</button>' +
      '<div class="_eli3_askdock_pbody" id="_eli3_askdock_pbody"></div>';
    document.body.appendChild(_panel);
    _panelBody = _panel.querySelector("#_eli3_askdock_pbody");
    _panel.querySelector("._eli3_askdock_pclose").onclick = _close;

    _positionChrome();
    try { window.addEventListener("resize", _positionChrome); } catch (_e) {}
  }

  // ── Open / close ─────────────────────────────────────────────────
  function _openDock() {
    if (!_enabled) return;
    _build();
    if (_hideTimer) { clearTimeout(_hideTimer); _hideTimer = null; }
    _positionChrome();
    _panel.style.display = "flex";
    _backdrop.style.display = "block";
    // Fresh render each open: clear, then render Ask ELI into the panel body.
    // Conversation persists via ask_eli's _sharedSessionHistory; the doc
    // mapping/index is docHash-cached so this does NOT re-map.
    if (_panelBody) _panelBody.innerHTML = "";
    _isOpen = true;
    _openedAt = Date.now();
    // Force handle visible regardless of any prior _updateVisibility hide.
    if (_handle) {
      _handle.style.setProperty("display", "inline-flex", "important");
      // Ensure handle is a child of BODY (not header) so its z-index can
      // win against the panel. If it drifted into the header, move it back.
      if (_handle.parentNode !== document.body) {
        try { document.body.appendChild(_handle); } catch (_e) {}
      }
    }
    requestAnimationFrame(function () {
      if (_backdrop) _backdrop.classList.add("_eli3_askdock_show");
      if (_panel) _panel.classList.add("_eli3_askdock_open");
      if (_handle) _handle.classList.add("_eli3_askdock_open");
    });
    var render = function () {
      if (!_isOpen) return; // user closed before load finished
      try { eli.dispatch("ask_eli", "openPanel", { mount: _panelBody, onClose: _close }); }
      catch (e) { if (typeof showToast === "function") showToast("Ask ELI failed to open: " + (e && e.message || "unknown"), "err"); }
    };
    if (eli.tools && typeof eli.tools.ensureLoaded === "function") {
      eli.tools.ensureLoaded("ask_eli").then(render).catch(render);
    } else { render(); }
    try { if (eli.stats && eli.stats.record) eli.stats.record("appOpenedAskDock"); } catch (_e) {}
  }

  function _close() {
    // Look up panel/backdrop/handle by id so stale JS references can't
    // make close a no-op. (If a re-render replaced our nodes, our _panel
    // variable would point to detached DOM; live lookup is robust.)
    var pnl = _panel || document.getElementById("_eli3_askdock_panel");
    var bd = _backdrop || document.getElementById("_eli3_askdock_backdrop");
    var hd = _handle || document.querySelector('[data-ask-dock-handle]');
    if (!pnl) return;
    _isOpen = false;
    if (bd) bd.classList.remove("_eli3_askdock_show");
    if (pnl) pnl.classList.remove("_eli3_askdock_open");
    if (hd) hd.classList.remove("_eli3_askdock_open");
    // Repoint module refs to live nodes so the hide-timer below works
    // against current DOM regardless of which path got us here.
    _panel = pnl; _backdrop = bd; _handle = hd;
    _panelBody = pnl.querySelector("#_eli3_askdock_pbody") || _panelBody;
    // After the slide-out transition, hide + tear down the Ask ELI instance
    // (clearing the body fires ask_eli's DOM-removal watchdog → frees its
    // selection poller). Conversation is safe in _sharedSessionHistory.
    _hideTimer = setTimeout(function () {
      if (_isOpen) return;
      if (_panel) _panel.style.display = "none";
      if (_backdrop) _backdrop.style.display = "none";
      if (_panelBody) _panelBody.innerHTML = "";
    }, 300);
  }

  // ── Enable/disable (kill switch) ─────────────────────────────────
  function _applyEnabled() {
    if (_enabled && !_built) _build();
    if (!_handle) return;
    _positionChrome();
    _updateVisibility(); // honors both the kill switch and the on-home rule
  }

  // ── Boot: ALWAYS build the chrome (never gated on the setting) ────
  // Self-healing: retried until the handle actually lands AND the header
  // has measurable height. Any transient throw resets _built so the next
  // tick rebuilds cleanly. Visibility (kill switch + on-home) is handled by
  // _updateVisibility, NOT by gating the build.
  var tries = 0;
  (function _ensure() {
    try {
      _build();
      _applyEnabled();
      _positionChrome();
      _matchHeaderLook();
    } catch (e) {
      _built = false; // allow a clean retry next tick
      try { eli.log.event("tool", "ask_dock_build_retry", { msg: e && e.message }); } catch (_e) {}
    }
    var landed = !!document.getElementById("_eli3_askdock_handle");
    if ((!landed || _headerBottom() === 0) && tries++ < 40) {
      setTimeout(_ensure, 250);
      return;
    }
    _watchView(); // toggle handle visibility as the user moves between home and tools
  })();
  // Re-confirm the kill switch once the settings layer is surely ready
  // (an admin-disabled value may not have been readable at preload-idle boot).
  setTimeout(_refreshEnabled, 1500);

  // Auto-close on Home navigation IF the panel is currently open.
  // Earlier I removed this because it was firing during render-cycle
  // transients and killing newly-opened panels — but with debounce + open
  // check, it's safe AND it fixes the "Go Home doesn't close" report.
  // We debounce 100ms to ignore mid-open noise; a real user clicking home
  // is way past that window.
  try {
    if (eli.bus && typeof eli.bus.on === "function") {
      eli.bus.on("home:navigate", function () {
        // 500ms grace period — ignore any home:navigate that fires right
        // after the dock opens. Some kernel/tool paths emit it spuriously
        // during render. A real user click on Home is way past 500ms.
        if (Date.now() - _openedAt < 500) return;
        _currentToolId = null;
        if (_isOpen) _close();
        _updateVisibility();
      });
      // Track the active tool surface for the allowlist gate. Kernel
      // emits this from _launchTile (additive event, no apiVersion bump).
      eli.bus.on("tool:open", function (payload) {
        _currentToolId = (payload && payload.id) || null;
        _updateVisibility();
      });
    }
  } catch (_e) {}

  // Re-match the header look AND re-measure position whenever the body's
  // class list changes (kernel toggles `light-mode` for theme switches).
  // Without the _positionChrome call, the handle's cached `top` (set at
  // boot) becomes stale if the theme's CSS shifts header padding/height
  // even slightly — manifested as the closed-state handle overlapping
  // the header in light mode while the open-state was fine because
  // _openDock re-runs _positionChrome.
  try {
    var bodyObs = new MutationObserver(function () {
      _matchHeaderLook();
      _positionChrome();
    });
    bodyObs.observe(document.body, { attributes: true, attributeFilter: ["class"] });
  } catch (_e) {}

  // Esc closes the panel — guaranteed escape hatch.
  try {
    document.addEventListener("keydown", function (e) {
      if (_isOpen && (e.key === "Escape" || e.keyCode === 27)) _close();
    });
  } catch (_e) {}

  // Handle resurrection: if anything (a re-render, accidental cleanup,
  // etc.) removes the handle from the DOM, re-append it. The handle is
  // now a child of the header, so a header re-render would wipe it. This
  // observer catches that and restores it within one tick.
  try {
    var resurrectObs = new MutationObserver(function () {
      // Body subtree changed — could be the loading overlay being added
      // or removed. Cheap debounced visibility recheck catches it.
      if (!_visTimer) {
        _visTimer = setTimeout(function () { _visTimer = null; _updateVisibility(); }, 80);
      }
      if (_built && _handle && !document.contains(_handle)) {
        // Put the handle back in BODY, not in the header. The header is a
        // stacking context (position:relative + z-index:100) — any handle
        // inside it is z-index-trapped below body-level elements like the
        // open panel (which sits at z-index:10001 in body). The handle MUST
        // stay in body so its z-index:10002 wins globally.
        try { document.body.appendChild(_handle); } catch (_e) {}
        _matchHeaderLook();
        _updateVisibility();
      }
      // Defensive: if handle drifted INTO the header for any reason, pull
      // it back out to body. This catches earlier-version DOM state too.
      if (_built && _handle && _handle.parentNode && _handle.parentNode !== document.body) {
        try { document.body.appendChild(_handle); } catch (_e) {}
      }
    });
    resurrectObs.observe(document.body, { childList: true, subtree: true });
  } catch (_e) {}

  eli.register({
    ask_dock: { open: _openDock, close: _close },
  });

  eli.log.event("tool", "ask_dock_initialized", { enabled: _enabled });
}

jsonTools.css:
/* ask_dock — pull-down Ask ELI handle + slide-down panel.
   Premium polish + light/dark theme support. The kernel marks dark mode with
   <body class="beta-ui-active"> and light mode adds .light-mode on top of it.
   Defaults to the dark palette; .light-mode overrides apply on top. */

/* ─── Handle (pulls down from the header) ────────────────────────── */
._eli3_askdock_handle {
  position: fixed;
  left: 50%;
  transform: translateX(-50%) translateZ(0);
  z-index: 10002;
  display: inline-flex;
  align-items: center;
  gap: 9px;
  padding: 4px 26px 6px;
  /* JS sets actual bg + color from the live header so the seam is invisible.
     These are the fallback dark-mode look. */
  background: linear-gradient(180deg, #1f2a44 0%, #0f172a 100%);
  color: #f8fafc;
  border: none;
  border-radius: 0;
  /* Trapezoid silhouette — wider top, narrower bottom. Reads as the
     header tapering down into the chevron. 10px diagonal cuts on
     each bottom corner give the sloped sides. */
  clip-path: polygon(0 0, 100% 0, calc(100% - 10px) 100%, 10px 100%);
  /* Gold outline on left/right/bottom only. Stacked drop-shadows
     follow the clipped shape (a regular CSS border can't — it tracks
     the bounding box, not the polygon). No upward shadow → no top
     outline → the seam with the header stays continuous. */
  filter: drop-shadow(-2px 0 0 #c9a227)
          drop-shadow(2px 0 0 #c9a227)
          drop-shadow(0 2px 0 #c9a227);
  cursor: pointer;
  font: 700 10px/1 Inter, "Segoe UI", system-ui, -apple-system, sans-serif;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  /* No box-shadow — the kernel header already casts one downward, and
     clip-path would crop it anyway. */
  box-shadow: none;
  transition:
    transform 0.18s cubic-bezier(0.2, 0.8, 0.2, 1),
    filter 0.18s ease;
  will-change: transform, filter;
}
._eli3_askdock_handle:hover {
  filter: brightness(1.08);
}
._eli3_askdock_handle:active {
  transform: translateX(-50%) translateY(1px) translateZ(0);
  filter: brightness(0.96);
}
._eli3_askdock_label {
  font-size: 10px;
  font-weight: 700;
  letter-spacing: 0.1em;
  text-transform: uppercase;
  line-height: 1;
  opacity: 0.95;
}
._eli3_askdock_chev {
  display: inline-block;
  font-size: 18px;
  line-height: 0;            /* Don't let the bigger glyph push the button taller */
  margin: -4px 0;            /* Pull vertical bounds back to match the label */
  font-weight: 900;
  color: #e7c14e;
  transition: transform 0.32s cubic-bezier(0.2, 0.8, 0.2, 1);
  filter: drop-shadow(0 0 6px rgba(231, 193, 78, 0.3));
}
._eli3_askdock_handle._eli3_askdock_open ._eli3_askdock_chev {
  transform: rotate(180deg);
}

/* Light-mode handle — same "no shadow" rule. JS still overrides bg/color
   from the live header sample via _matchHeaderLook + luminance pick.
   Outline stays gold via the same drop-shadow stack as the dark default. */
body.light-mode ._eli3_askdock_handle {
  background: linear-gradient(180deg, #ffffff 0%, #f1f5f9 100%);
  color: #0f172a;
  box-shadow: none;
}
body.light-mode ._eli3_askdock_chev {
  color: #b8901f;
  filter: none;
}

/* ─── Backdrop (dimmer under the panel) ──────────────────────────── */
._eli3_askdock_backdrop {
  position: fixed;
  left: 0;
  right: 0;
  bottom: 0;
  z-index: 9990;
  background: rgba(15, 23, 42, 0);
  pointer-events: none;
  backdrop-filter: blur(0px);
  -webkit-backdrop-filter: blur(0px);
  transition:
    background 0.35s cubic-bezier(0.2, 0.8, 0.2, 1),
    backdrop-filter 0.35s ease;
}
._eli3_askdock_backdrop._eli3_askdock_show {
  background: rgba(15, 23, 42, 0.5);
  backdrop-filter: blur(3px);
  -webkit-backdrop-filter: blur(3px);
  pointer-events: auto;
}

/* ─── Panel (slides down from the header) ───────────────────────── */
._eli3_askdock_panel {
  position: fixed;
  left: 0;
  right: 0;
  z-index: 10001;
  display: flex;
  flex-direction: column;
  background: #f8fafc;
  border-bottom: 3px solid #c9a227;
  box-shadow:
    0 20px 50px -8px rgba(0, 0, 0, 0.45),
    0 8px 20px -4px rgba(0, 0, 0, 0.25);
  transform: translateY(-110%) translateZ(0);
  /* Premium "spring" easing — slightly slower, settles smoothly */
  transition: transform 0.42s cubic-bezier(0.22, 1, 0.36, 1);
  overflow: hidden;
  will-change: transform;
}
._eli3_askdock_panel._eli3_askdock_open {
  transform: translateY(0) translateZ(0);
}

/* Floating close button — top-right of the panel, no header bar.
   Ask ELI renders its own header inside; we don't duplicate it. */
._eli3_askdock_pclose {
  position: absolute;
  top: 10px;
  right: 12px;
  z-index: 5;
  width: 30px;
  height: 30px;
  border-radius: 8px;
  background: rgba(15, 23, 42, 0.06);
  border: 1px solid rgba(15, 23, 42, 0.08);
  color: #475569;
  font-size: 13px;
  cursor: pointer;
  transition:
    background 0.15s ease,
    color 0.15s ease,
    transform 0.12s ease;
}
._eli3_askdock_pclose:hover {
  background: rgba(15, 23, 42, 0.12);
  color: #0f172a;
  transform: scale(1.06);
}
._eli3_askdock_pclose:active { transform: scale(0.96); }
body.light-mode ._eli3_askdock_pclose {
  background: rgba(15, 23, 42, 0.06);
  color: #475569;
}

/* Body — Ask ELI renders in here. */
._eli3_askdock_pbody {
  flex: 1 1 auto;
  min-height: 0;
  overflow: auto;
  position: relative;
  background: #f8fafc;
}
._eli3_askdock_pbody > * { height: 100%; }

/* Light-mode panel — soft cream surface, navy text, same gold accents */
body.light-mode ._eli3_askdock_panel {
  background: #fdfdfb;
  box-shadow:
    0 18px 44px -8px rgba(15, 23, 42, 0.22),
    0 6px 16px -4px rgba(15, 23, 42, 0.12);
}
body.light-mode ._eli3_askdock_pbody { background: #fdfdfb; }

/* Reduced-motion: still animate, but quicker + simpler (don't disable —
   the slide is the whole UX). */
@media (prefers-reduced-motion: reduce) {
  ._eli3_askdock_panel,
  ._eli3_askdock_backdrop,
  ._eli3_askdock_chev {
    transition-duration: 0.18s !important;
  }
}
